fn handle_tile_map_pointer(
    ui: &mut egui::Ui,
    response: &egui::Response,
    loaded: &mut LoadedTileMap,
    layer: &engine_authoring::TileLayerId,
    pointer_cell: Option<engine_authoring::TileCell>,
    tool: TileTool2d,
    bounds: engine_authoring::TileRect,
    work_budget: usize,
) -> Result<(), String> {
    if ui.input(|input| input.key_pressed(egui::Key::Escape)) {
        loaded.cancel_gesture()?;
        return Ok(());
    }
    let released = ui.input(|input| input.pointer.any_released());

    match tool {
        TileTool2d::Paint | TileTool2d::Erase => {
            let tile = if tool == TileTool2d::Erase {
                None
            } else {
                loaded.selected_tile.clone()
            };
            if response.drag_started()
                && let Some(cell) = pointer_cell
            {
                loaded
                    .service
                    .begin_gesture()
                    .map_err(|error| error.to_string())?;
                loaded.gesture_active = true;
                loaded
                    .service
                    .paint(layer, cell, tile.clone())
                    .map_err(|error| error.to_string())?;
            } else if loaded.gesture_active
                && response.dragged()
                && let Some(cell) = pointer_cell
            {
                loaded
                    .service
                    .paint(layer, cell, tile)
                    .map_err(|error| error.to_string())?;
            }
            if loaded.gesture_active && released {
                loaded.commit_gesture()?;
            }
        }
        TileTool2d::Rectangle | TileTool2d::Line => {
            if response.drag_started() {
                loaded.gesture_start = pointer_cell;
            }
            if released
                && let (Some(start), Some(end)) = (loaded.gesture_start.take(), pointer_cell)
            {
                let tile = loaded.selected_tile.clone();
                run_one_shot_gesture(loaded, |service| {
                    if tool == TileTool2d::Rectangle {
                        service.rectangle(
                            layer,
                            engine_authoring::TileRect::from_corners(start, end),
                            tile,
                            work_budget,
                        )
                    } else {
                        service.line(layer, start, end, tile, work_budget)
                    }
                })?;
            }
        }
        TileTool2d::Fill => {
            if response.clicked()
                && let Some(cell) = pointer_cell
            {
                let tile = loaded.selected_tile.clone();
                run_one_shot_gesture(loaded, |service| {
                    service.fill_bounded(layer, cell, bounds, tile, work_budget)
                })?;
            }
        }
        TileTool2d::Eyedropper => {
            if response.clicked()
                && let Some(cell) = pointer_cell
            {
                loaded.selected_tile = loaded.service.eyedropper(layer, cell);
            }
        }
        TileTool2d::SelectStamp => {
            if loaded.stamp.cells.is_empty() {
                if response.drag_started() {
                    loaded.gesture_start = pointer_cell;
                }
                if released
                    && let (Some(start), Some(end)) =
                        (loaded.gesture_start.take(), pointer_cell)
                {
                    loaded.stamp = loaded.service.copy_stamp(
                        layer,
                        engine_authoring::TileRect::from_corners(start, end),
                    );
                }
            } else if response.clicked()
                && let Some(origin) = pointer_cell
            {
                let stamp = loaded.stamp.clone();
                run_one_shot_gesture(loaded, |service| {
                    service.paste_stamp(layer, origin, &stamp, work_budget)
                })?;
            }
        }
    }
    Ok(())
}

fn run_one_shot_gesture(
    loaded: &mut LoadedTileMap,
    operation: impl FnOnce(
        &mut engine_authoring::TileMapAuthoringService,
    ) -> Result<(), engine_authoring::Native2dAuthoringError>,
) -> Result<(), String> {
    loaded
        .service
        .begin_gesture()
        .map_err(|error| error.to_string())?;
    loaded.gesture_active = true;
    if let Err(error) = operation(&mut loaded.service) {
        let _ = loaded.cancel_gesture();
        return Err(error.to_string());
    }
    loaded.commit_gesture()
}

